SELECT CAST(COUNT(DISTINCT CASE WHEN a.readmit_30d THEN a.stay_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.stay_id), 0) AS readmission_rate, AVG(CASE WHEN a.readmit_30d THEN a.length_of_stay END) AS avg_length_of_stay_for_readmitted, AVG(CASE WHEN NOT a.readmit_30d THEN a.length_of_stay END) AS avg_length_of_stay_for_non_readmitted, CAST(COUNT(DISTINCT CASE WHEN a.length_of_stay > 10 THEN a.stay_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.stay_id), 0) AS proportion_of_stays_over_10_days FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND p.anchor_age = 88 AND p.anchor_year_group BETWEEN 83 AND 93 AND a.admission_type = 'ED' AND a.principal_diagnosis = 'TIA';